input.sparql:
SELECT ?ts ?node WHERE {
  ?sensor a brick:AirTemperatureSensor ;
          brick:hasLocation ?loc ;
          ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
  FILTER(str(?loc) = "DataCenter_basement_ZN_6" || strstarts(str(?loc), "DataCenter_basement_ZN_6"))
}

SELECT ?z WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?l .
  FILTER(str(?l) = "DataCenter_basement_ZN_6")
}

SELECT ?sensor ?ext ?ts WHERE {
  ?sensor brick:isPointOf ?zone .
  FILTER(?zone = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z06>)
  ?sensor brick:ref:hasExternalReference ?ext .
  ?ext brick:ref:hasTimeseriesId ?ts .
}

SELECT ?sensor ?type ?ext ?ts WHERE {
  ?sensor brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z06> .
  OPTIONAL { ?sensor a ?type . }
  OPTIONAL { ?sensor ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?ts . }
}
